"""Package the native renders and real films as one offline presentation."""
import json,shutil,subprocess,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];WORK=ROOT/'work/jury_release_20261014';OUT=ROOT/'outputs/jury_release_20261014'
SLIDES=OUT/'offline_slides';SLIDES.mkdir(exist_ok=True)
for variant in ['compact','extended','friday']:
    for f in (WORK/('render-'+variant)).glob('*.png'):
        shutil.copy2(f,SLIDES/(variant+'-'+f.name))
timing=json.loads((WORK/'timing.json').read_text())
scenario=json.loads((OUT/'PRESENTATION_SCENARIO.json').read_text(encoding='utf8'))
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invisible Shield / offline jury presentation</title>
<style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#102e37;color:#f5f3e9;font:18px/1.5 "Segoe UI",Arial,sans-serif}button,select{font:inherit;cursor:pointer}button{padding:13px 24px;background:#ecefdf;color:#12313a;border:0;margin:8px 12px 8px 0}button:focus-visible,a:focus-visible{outline:3px solid #d7ae70;outline-offset:5px}a{color:#e6c998}h1{font:52px/1.1 Georgia,serif;max-width:820px;margin:20px 0 26px}.eyebrow{font-size:14px;letter-spacing:.12em;color:#b2c7ba}#menu{max-width:1150px;padding:55px 45px;margin:auto}.menu-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:65px}.menu-grid p{max-width:650px}.secondary{background:transparent;color:#f5f3e9;border:1px solid #96afa5}.files{border-top:1px solid #516967;padding-top:20px;font-size:16px}.files a{display:inline-block;margin:5px 20px 5px 0}#stage{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:#0b1518}.canvas{width:min(100vw,177.7778vh);aspect-ratio:16/9;position:relative;overflow:hidden;background:#12313a}.canvas img,.canvas video{position:absolute;width:100%;height:100%;object-fit:contain;inset:0}.canvas video{display:none}#reveal{opacity:0;transition:opacity .8s}#control{position:fixed;left:20px;bottom:12px;z-index:5;opacity:0;transition:opacity .2s;font-size:15px;background:#102e37e8;padding:4px 12px}#control:hover,#control:focus-within,body.paused #control{opacity:1}#control button{padding:5px 12px;font-size:15px;margin:3px}#finish{display:none;position:fixed;inset:0;z-index:6;background:#102e37;text-align:center;padding:15vh 8vw}#finish h1{margin:25px auto}#status{color:#c7d4cc;font-size:15px}#error{background:#8b362b;color:white;padding:15px;display:none}#video-controls{display:none}body.demo #video-controls{display:block}.limit{font-size:14px;color:#bdd0c6}@media(max-width:800px){#menu{padding:28px}.menu-grid{grid-template-columns:1fr;gap:20px}h1{font-size:38px}}</style>
<div id="menu"><p class="eyebrow">OCEAN HACKATHON CORK / ORK02</p><h1>Seeing the Invisible Shield</h1><div class="menu-grid"><div><p>A complete offline jury presentation, with the real application film playing inside the same page.</p><label for="variant">Rehearsal version </label><select id="variant"><option value="compact">3 minutes, including 30-second film</option><option value="extended">5 minutes, including 55-second film</option></select><p><button id="start">Start timed presentation</button><button id="manual" class="secondary">Manual presentation</button></p><p class="limit">Confirm the official speaking slot with the organiser. Press F11 for full screen. Space pauses. Left/right arrows navigate. Escape returns here.</p><p id="status">Ready offline. No server or internet connection needed.</p><div id="error" role="alert"></div></div><div><p class="eyebrow">REHEARSE A SEGMENT</p><button id="friday" class="secondary">Friday invitation</button><button id="demo55" class="secondary">55-second film</button><button id="demo30" class="secondary">30-second film</button><p class="limit">Friday is an invitation to collaborate, before the weekend work. Editable PowerPoints and exact English speaker notes are beside this file.</p><a href="ASSESSMENT_PILOT.pdf">Open the generated assessment PDF</a></div></div><div class="files"><a href="SUNDAY_3_MINUTES_FINAL.pptx">Editable 3-minute deck</a><a href="SUNDAY_5_MINUTES_FINAL.pptx">Editable 5-minute deck</a><a href="FRIDAY_INVITATION.pptx">Friday deck</a><a href="SUNDAY_3_MINUTES.md">3-minute speaker notes</a><a href="SUNDAY_5_MINUTES.md">5-minute speaker notes</a><a href="VISUAL_ASSETS_AND_SOURCES.md">Credits and sources</a><a href="KULLANIM_TR.html">Türkçe kullanım</a></div></div>
<div id="stage"><div class="canvas"><img id="base" alt="Jury presentation slide"><img id="reveal" alt="Purposeful geographic or model reveal"><video id="movie" muted playsinline preload="auto"></video></div></div><div id="control"><button id="prev" aria-label="Previous scene">←</button><button id="pause">Pause</button><button id="next" aria-label="Next scene">→</button><button id="menu-button">Menu</button><span id="position"></span></div><div id="finish"><p class="eyebrow">PRESENTATION COMPLETE</p><h1>A shared brief for the next coastal survey</h1><button id="again">Return to the start</button><p><a href="ASSESSMENT_PILOT.pdf">View the generated assessment</a></p></div>
<script>
const times=__TIMINGS__,q=id=>document.getElementById(id),movie=q('movie');let variant='compact',index=0,running=false,automatic=false,paused=false,started=0,pausedAt=0,mode='deck',timer,elapsed=0,history=[];
function menu(){running=false;clearInterval(timer);movie.pause();q('stage').style.display='none';q('control').style.display='none';q('finish').style.display='none';q('menu').style.display='block';document.body.classList.remove('paused');}
function asset(i,suffix=''){return 'offline_slides/'+variant+'-slide-'+(i+1)+suffix+'.png';}
function show(i){if(mode==='deck'&&i>5){running=false;movie.pause();clearInterval(timer);q('finish').style.display='block';return;}index=Math.max(0,i);elapsed=0;started=performance.now();if(paused)pausedAt=started;movie.pause();movie.style.display='none';movie.controls=false;q('reveal').style.opacity=0;q('reveal').removeAttribute('src');q('base').style.display='block';q('position').textContent=(index+1)+' / '+(mode==='deck'?6:1);history.push({scene:index+1,at:performance.now()});
 if(mode==='friday')q('base').src='offline_slides/friday-slide-1.png';
 else if(mode==='film'||index===4){q('base').style.display='none';movie.style.display='block';movie.src=variant==='compact'?'DEMO_30_SECONDS.mp4':'DEMO_55_SECONDS.mp4';movie.currentTime=0;movie.controls=mode==='film';if(!paused)movie.play().catch(e=>{q('error').textContent='Playback needs a click: return to the menu and start again. '+e.message;q('error').style.display='block';});}
 else {q('base').src=asset(index,index===1?'-initial':index===3?'-without':'');if(index===1||index===3)q('reveal').src=asset(index);}
}
function start(auto,v=q('variant').value,m='deck'){variant=v;mode=m;automatic=auto;running=true;paused=false;history=[];q('menu').style.display='none';q('finish').style.display='none';q('stage').style.display='flex';q('control').style.display='block';q('pause').textContent='Pause';document.body.classList.remove('paused');show(0);clearInterval(timer);timer=setInterval(tick,60);}
function tick(){if(!running||paused)return;elapsed=(performance.now()-started)/1000;if(mode==='deck'&&((index===1&&elapsed>=12)||(index===3&&elapsed>=3)))q('reveal').style.opacity=1;if(automatic&&mode==='deck'&&index!==4&&elapsed>=times[variant][index])show(index+1);}
movie.addEventListener('ended',()=>{if(running&&automatic&&mode==='deck')show(5);});movie.addEventListener('error',()=>{q('error').textContent='Movie file could not be opened. Keep the two MP4 files beside this page.';q('error').style.display='block';});
function toggle(){if(!running)return;paused=!paused;document.body.classList.toggle('paused',paused);q('pause').textContent=paused?'Resume':'Pause';if(paused){pausedAt=performance.now();movie.pause();}else{started+=performance.now()-pausedAt;if(mode==='film'||(mode==='deck'&&index===4))movie.play();}}
q('start').onclick=()=>start(true);q('manual').onclick=()=>start(false);q('friday').onclick=()=>start(false,'compact','friday');q('demo55').onclick=()=>start(false,'extended','film');q('demo30').onclick=()=>start(false,'compact','film');q('pause').onclick=toggle;q('next').onclick=()=>{if(mode==='deck')show(index+1);};q('prev').onclick=()=>{if(mode==='deck')show(index-1);};q('menu-button').onclick=menu;q('again').onclick=menu;
addEventListener('keydown',e=>{if(!running)return;if(e.key==='Escape'){e.preventDefault();menu();}if(e.code==='Space'){e.preventDefault();toggle();}if(e.key==='ArrowRight'&&mode==='deck'){e.preventDefault();show(index+1);}if(e.key==='ArrowLeft'&&mode==='deck'){e.preventDefault();show(index-1);}});
window.OfflinePitch=Object.freeze({getState:()=>({variant,index,running,automatic,paused,mode,elapsed,history,videoTime:movie.currentTime,videoDuration:movie.duration})});
</script></html>'''
html=html.replace('Ready offline. No server or internet connection needed.','Ready offline. Build '+scenario['build_id']+' / '+scenario['id']+'. Seven-cell pilot, 1.75 ha. No server or internet needed.')
html=html.replace('Open the generated assessment PDF','Open the printed assessment PDF').replace('<div class="files">','<div class="files"><a href="PRESENTATION_SCENARIO.json">Exact presentation scenario</a><a href="ASSESSMENT_PILOT.html">Downloaded HTML report</a>')
(OUT/'OFFLINE_PRESENTATION.html').write_text(html.replace('__TIMINGS__',json.dumps(timing)),encoding='utf8')
(OUT/'OFFLINE_DEMO.html').write_text('<!doctype html><meta charset="utf-8"><title>Offline application films</title><style>body{margin:4%;background:#102e37;color:#f5f3e9;font:20px Segoe UI}video{display:block;max-width:100%;width:1100px;margin:20px 0}a{color:#e4c997}</style><h1>The real application workflow</h1><p>Select an area, inspect evidence, calculate scenarios, download a report.</p><video controls preload="metadata" src="DEMO_55_SECONDS.mp4"></video><p>55 seconds / no subtitles or overlays; narrate live</p><video controls preload="metadata" src="DEMO_30_SECONDS.mp4"></video><p>30 seconds / no subtitles or overlays; narrate live</p><a href="OFFLINE_PRESENTATION.html">Complete jury presentation</a><p><a href="VISUAL_ASSETS_AND_SOURCES.md">Sources and credits</a></p>',encoding='utf8')
launcher='@echo off\r\nsetlocal\r\nset "jury_chrome=C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe"\r\nif exist "%jury_chrome%" (\r\n start "" "%jury_chrome%" --new-window "%~dp0OFFLINE_PRESENTATION.html"\r\n) else (\r\n start "" "%~dp0OFFLINE_PRESENTATION.html"\r\n)\r\n'
(OUT/'START_PRESENTATION.bat').write_bytes(launcher.encode('ascii'))
(ROOT/'START_JURY_PRESENTATION.bat').write_bytes('@echo off\r\ncall "%~dp0outputs\\jury_release_20261014\\START_PRESENTATION.bat"\r\n'.encode('ascii'))
print('Offline presentation and launchers prepared')
